// @name JSX: Word clock
// @background #0a0a0a
// @refresh 30
// A word clock: the letters that tell the time lit, the rest faint, and a dot
// for each minute past the five.
// `at` (a field) pins the time, for a snapshot; empty, it is the clock.
const rows = ['ITLISASAMPM', 'ACQUARTERDC', 'TWENTYFIVEX', 'HALFSTENFTO', 'PASTERUNINE',
  'ONESIXTHREE', 'FOURFIVETWO', 'EIGHTELEVEN', 'SEVENTWELVE', 'TENSEOCLOCK']
// [row, first letter, length]
const W = {
  IT: [0, 0, 2], IS: [0, 3, 2], AM: [0, 7, 2], PM: [0, 9, 2], A: [1, 0, 1], QUARTER: [1, 2, 7],
  TWENTY: [2, 0, 6], FIVE_M: [2, 6, 4], HALF: [3, 0, 4], TEN_M: [3, 5, 3], TO: [3, 9, 2],
  PAST: [4, 0, 4], OCLOCK: [9, 5, 6],
}
const hours = [[8, 5, 6], [5, 0, 3], [6, 8, 3], [5, 6, 5], [6, 0, 4], [6, 4, 4],
  [5, 3, 3], [8, 0, 5], [7, 0, 5], [4, 7, 4], [9, 0, 3], [7, 5, 6]] // twelve, one .. eleven
const minuteWords = [
  ['OCLOCK'], ['FIVE_M', 'PAST'], ['TEN_M', 'PAST'], ['A', 'QUARTER', 'PAST'], ['TWENTY', 'PAST'],
  ['TWENTY', 'FIVE_M', 'PAST'], ['HALF', 'PAST'], ['TWENTY', 'FIVE_M', 'TO'], ['TWENTY', 'TO'],
  ['A', 'QUARTER', 'TO'], ['TEN_M', 'TO'], ['FIVE_M', 'TO'],
]

export function get(app) {
  const now = app.config.at ? new Date(app.config.at) : new Date()
  const five = Math.floor(now.getMinutes() / 5)
  const hour = (now.getHours() + (five > 6 ? 1 : 0)) % 12
  const lit = [W.IT, W.IS, now.getHours() < 12 ? W.AM : W.PM, hours[hour], ...minuteWords[five].map((w) => W[w])]
  const on = (r, c) => lit.some(([row, start, n]) => row === r && c >= start && c < start + n)
  const extra = now.getMinutes() % 5
  return (
    <div className="flex flex-col items-center justify-center gap-6 bg-neutral-950">
      <div className="grid grid-cols-11 gap-x-3 gap-y-1">
        {rows.flatMap((row, r) => row.split('').map((ch, c) => (
          <span className={`text-3xl text-center ${on(r, c) ? 'text-amber-200 font-bold' : 'text-neutral-800'}`}>{ch}</span>
        )))}
      </div>
      <div className="flex gap-4">
        {[1, 2, 3, 4].map((i) => (
          <div className={`w-3 h-3 rounded-full ${i <= extra ? 'bg-amber-200' : 'bg-neutral-800'}`} />
        ))}
      </div>
    </div>
  )
}
